let particles=[];
function spawnBurst(x,z,y,color,n=18){for(let i=0;i<n;i++)particles.push({x,z,y,vx:rand(-2.7,2.7),vz:rand(-2.8,2.8),vy:rand(.8,3.8),life:rand(.35,.8),max:.8,color})}
function drawBall(t){for(const tr of ball.trail){const p=project(tr.x,tr.z,tr.y);ctx.globalAlpha=tr.life*.46;glow(p.x,p.y,12*p.s,'rgba(216,255,62,ALPHA)',1);ellipse(p.x,p.y,3.5*p.s,3.5*p.s,'rgba(216,255,105,.65)')}ctx.globalAlpha=1;
 const p=project(ball.x,ball.z,ball.y),shadow=project(ball.x,ball.z,0);ellipse(shadow.x,shadow.y,5*shadow.s+ball.y*1.1,2*shadow.s,'rgba(0,8,12,.44)');glow(p.x,p.y,23*p.s,'rgba(216,255,62,ALPHA)',.45);ellipse(p.x,p.y,4.8*p.s,4.8*p.s,'#e5ff78');ctx.strokeStyle='#547523';ctx.lineWidth=1*p.s;ctx.beginPath();ctx.arc(p.x,p.y,3.6*p.s,-1.1,1.3);ctx.stroke();
}
function label(text,x,y,color,size=10){ctx.font=`500 ${size}px "DM Mono", monospace`;ctx.textAlign='center';ctx.fillStyle=color;ctx.fillText(text,x,y)}
function draw(t){ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));background(t);courtScene(t);
 // volumetric spotlights
 const p=project(0,5);const beam=ctx.createLinearGradient(0,H*.18,0,p.y);beam.addColorStop(0,'rgba(110,255,218,.025)');beam.addColorStop(1,'rgba(110,255,218,0)');ctx.fillStyle=beam;ctx.beginPath();ctx.moveTo(W*.42,H*.17);ctx.lineTo(W*.58,H*.17);ctx.lineTo(W*.75,p.y);ctx.lineTo(W*.25,p.y);ctx.fill();
 drawPlayer(cpu,false,t);drawPlayer(player,true,t);drawBall(t);
 for(const a of particles){const q=project(a.x,a.z,a.y);ctx.globalAlpha=clamp(a.life/a.max,0,1);ellipse(q.x,q.y,2.4*q.s,2.4*q.s,a.color)}ctx.globalAlpha=1;
 // floating player IDs
 let pp=project(player.x,player.z),cp=project(cpu.x,cpu.z);label('YOU',pp.x,pp.y+29*pp.s,'rgba(232,255,191,.75)',9);label('CPU',cp.x,cp.y+28*cp.s,'rgba(255,191,174,.75)',9);
 ctx.restore();}
function point(who){if(mode!=='play')return;mode='point';combo=0;updateHud();if(who==='you')scoreYou++;else scoreCpu++;$('scoreYou').textContent=scoreYou;$('scoreCpu').textContent=scoreCpu;
 const toast=$('toast');toast.classList.remove('hidden');if(scoreYou>=5||scoreCpu>=5){toast.innerHTML=scoreYou>=5?'<h1>COURT<br><em>DOMINATED.</em></h1><p>THE CROWD WILL REMEMBER THIS.</p><div class="cta">▶ &nbsp; PLAY AGAIN</div>':'<h1>MATCH<br><em>OVER.</em></h1><p>THE ROBOT CLAIMS THE COURT.</p><div class="cta">▶ &nbsp; REMATCH</div>';mode='over'}else{toast.innerHTML=`<h1>${who==='you'?'POINT':'POINT'} <em>${who==='you'?'YOU':'CPU'}!</em></h1><p>${who==='you'?'PERFECT PLAY. KEEP THE PRESSURE.':'RESET. THE COURT IS YOURS.'}</p><div class="cta">NEXT SERVE IN 2s</div>`;setTimeout(()=>{if(mode==='point'){toast.classList.add('hidden');resetBall(who==='cpu');mode='play'}},1800)}
}
function resetBall(cpuServe=false){player.x=clamp(player.x,-3.5,3.5);player.z=8.4;cpu.x=rand(-1.3,1.3);cpu.z=1.8;ball={x:cpuServe?cpu.x:player.x,z:cpuServe?1.9:8.25,y:.38,vx:0,vz:0,vy:0,trail:[],owner:cpuServe?'cpu':'you',bounces:0};$('servePill').textContent=cpuServe?'● ROBOT SERVE':'● YOUR SERVE';$('servePill').style.color=cpuServe?'#ff8377':'var(--lime)';serve(cpuServe)}
function serve(fromCpu){const dir=fromCpu?1:-1;ball.vx=rand(-1.1,1.1);ball.vz=dir*rand(6.6,7.7);ball.vy=rand(4.7,5.6);ball.bounces=0;flash=.2;$('flash').classList.remove('on');void $('flash').offsetWidth;$('flash').classList.add('on');}
function start(){if(mode==='play')return;if(mode==='over'){scoreYou=scoreCpu=0;$('scoreYou').textContent='0';$('scoreCpu').textContent='0';$('toast').innerHTML='<h1>OWN THE<br><em>COURT.</em></h1><p>THE FASTEST PADEL ARENA IN THE CITY</p><div class="cta">▶ &nbsp; PRESS ENTER TO PLAY</div><div class="sub">WASD MOVE &nbsp;·&nbsp; SPACE HIT &nbsp;·&nbsp; SHIFT DASH</div>'}mode='play';$('toast').classList.add('hidden');combo=0;resetBall(false)}
function updateHud(){ $('combo').textContent=`× ${combo} PERFECT RALLY`; $('combo').classList.toggle('on',combo>1);$('speed').textContent=String(Math.round(speed*21)).padStart(3,'0')}
let swingQueued=0;
function hit(isCpu=false){const p=isCpu?cpu:player;p.swing=.32;if(isCpu){if(Math.abs(ball.z-cpu.z)>2.1||Math.abs(ball.x-cpu.x)>2.4||ball.y>2.8)return;const tx=clamp((isCpu?player.x:cpu.x)+rand(-1.3,1.3),-4.1,4.1);ball.vx=(tx-ball.x)*.65+rand(-.8,.8);ball.vz=rand(6.6,8.5);ball.vy=rand(3.2,5.1);ball.bounces=0;ball.owner='cpu';spawnBurst(ball.x,ball.z,ball.y,'#ff746a',11);return}
 const dz=Math.abs(ball.z-player.z),dx=Math.abs(ball.x-player.x);if(dz>2.05||dx>2.0||ball.y>2.75)return;
 const timing=ball.y<1.25&&dz<1.1&&dx<1.1;combo++;const power=timing?9.8:7.8;const target=clamp(cpu.x+rand(-2.5,2.5),-4.2,4.2);ball.vx=clamp((target-ball.x)*.75+player.vx*.6,-6.5,6.5);ball.vz=-power;ball.vy=timing?rand(4.6,6.3):rand(3.4,5.2);ball.bounces=0;ball.owner='you';speed=Math.hypot(ball.vx,ball.vz);shake=timing?4:2;spawnBurst(ball.x,ball.z,ball.y,timing?'#e1ff52':'#a3ffc0',timing?25:13);updateHud();if(timing){$('servePill').textContent='⚡ PERFECT SMASH';$('servePill').style.color='var(--lime)'}else{$('servePill').textContent='● RALLY ON'}
}

