function update(dt){if(mode!=='play')return;
 const ax=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),az=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),dash=keys.shift?1.55:1;
 player.vx+=(ax*8*dash-player.vx)*Math.min(1,dt*10);player.vz+=(az*6.2*dash-player.vz)*Math.min(1,dt*10);player.x=clamp(player.x+player.vx*dt,-4.35,4.35);player.z=clamp(player.z+player.vz*dt,5.25,9.7);if(ax||az)player.run+=dt*8;player.swing=Math.max(0,player.swing-dt);player.dash=Math.max(0,player.dash-dt);
 const cTargetZ=ball.z<5.4?clamp(ball.z+.45,.45,4.7):1.8,cTargetX=ball.z<5.4?clamp(ball.x,-4.1,4.1):clamp(ball.x*.35,-2.5,2.5);cpu.vx+=(clamp((cTargetX-cpu.x)*3.2,-5.5,5.5)-cpu.vx)*Math.min(1,dt*4);cpu.vz+=(clamp((cTargetZ-cpu.z)*3,-3.5,3.5)-cpu.vz)*Math.min(1,dt*4);cpu.x=clamp(cpu.x+cpu.vx*dt,-4.35,4.35);cpu.z=clamp(cpu.z+cpu.vz*dt,.35,4.8);if(Math.abs(cpu.vx)+Math.abs(cpu.vz)>.7)cpu.run+=dt*8;cpu.swing=Math.max(0,cpu.swing-dt);
 if(keys.space){swingQueued=.18;keys.space=false}if(swingQueued>0){hit(false);swingQueued-=dt}
 if(ball.owner!=='cpu'&&ball.z<5.25&&Math.abs(ball.x-cpu.x)<1.55&&Math.abs(ball.z-cpu.z)<1.65&&ball.y<2.35)hit(true);
 ball.trail.unshift({x:ball.x,z:ball.z,y:ball.y,life:.8});if(ball.trail.length>8)ball.trail.pop();ball.trail.forEach(q=>q.life-=dt*2.7);ball.trail=ball.trail.filter(q=>q.life>0);
 const oldZ=ball.z;ball.x+=ball.vx*dt;ball.z+=ball.vz*dt;ball.y+=ball.vy*dt;ball.vy-=9.8*dt;
 if(ball.y<=.12){ball.y=.12;if(ball.vy<0){ball.vy=Math.abs(ball.vy)*.69;ball.vx*=.91;ball.vz*=.91;ball.bounces++;spawnBurst(ball.x,ball.z,.1,'#d7ff70',5);if(ball.bounces>=2){point(ball.owner);return}}}
 if(Math.abs(ball.x)>4.78){ball.x=clamp(ball.x,-4.78,4.78);ball.vx*=-.78;ball.vz*=.94;spawnBurst(ball.x,ball.z,ball.y,'#74f4d5',5)}
 if((ball.z<0||ball.z>10)&&ball.y<2.48){ball.z=clamp(ball.z,.05,9.95);ball.vz*=-.76;ball.vx*=.92;spawnBurst(ball.x,ball.z,ball.y,'#74f4d5',5)}
 if((oldZ<5&&ball.z>=5)||(oldZ>5&&ball.z<=5)){if(ball.y<.85){spawnBurst(ball.x,5,ball.y,'#ff746a',17);point(ball.owner==='you'?'cpu':'you');return}}
 if(ball.z<-.4||ball.z>10.4||ball.x<-5.4||ball.x>5.4){point(ball.owner==='you'?'cpu':'you');return}
 speed=Math.hypot(ball.vx,ball.vz);updateHud();if(shake>0)shake=Math.max(0,shake-dt*14);
 for(let i=particles.length-1;i>=0;i--){const a=particles[i];a.x+=a.vx*dt;a.z+=a.vz*dt;a.y+=a.vy*dt;a.vy-=6*dt;a.life-=dt;if(a.life<=0)particles.splice(i,1)}
}
function loop(t){const dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw(t);requestAnimationFrame(loop)}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k===' '?'space':k]=true;if(k==='enter')start();if(k===' '&&mode==='menu')start()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()===' '?'space':e.key.toLowerCase()]=false});
$('toast').addEventListener('click',start);canvas.addEventListener('pointerdown',()=>{if(mode==='menu'||mode==='over')start();else hit(false)});
document.querySelectorAll('.pad button').forEach(b=>{const key=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>keys[key]=false))});$('touchHit').addEventListener('pointerdown',e=>{e.preventDefault();hit(false)});
$('scoreYou').textContent='0';$('scoreCpu').textContent='0';requestAnimationFrame(loop);
})();
</script>
